// Generated by build.py from server/handler.js — do not edit here.
/* WAP CPD Events — server program (runs as a Supabase Edge Function).
 *
 * It runs the same rules engine as the website (core.js) on the server, against
 * ONE shared copy of the event data stored in Postgres. Every change happens in a
 * database transaction that locks the data row first, so two people booking at
 * the same moment are handled one after the other and the event can never be
 * overbooked.
 *
 * Who may do what:
 *  - Anyone: see the event and places left, make an RSVP, and use their own
 *    private booking / feedback / certificate link (a long secret token).
 *  - Staff: signed in with email and password (Supabase Auth); their role comes
 *    from the staff list in the event data. The rules engine checks each action.
 *  - Attendees never receive other attendees' details. The PA/Reception role does
 *    not receive the audit history or the anonymous feedback answers.
 *
 * This file has no imports, so the same code is used by the deployed function and
 * by the local tests. Dependencies are passed in by createHandler().
 */


// Rules-engine functions the website may ask the server to run.
const PUBLIC_FNS = new Set(['createBooking', 'updateDetails', 'cancelBooking', 'respondToOffer', 'submitFeedback']);
const STAFF_FNS = new Set([
  'createBooking', 'updateDetails', 'cancelBooking', 'makeOffer', 'respondToOffer', 'confirmLate', 'allocateContingencyFor',
  'releaseUnused', 'reinstate', 'recordArrival', 'undoArrival', 'confirmCompletion', 'recordEarlyDeparture', 'reviewEarlyDeparture',
  'undoCompletion', 'flagException', 'resolveException', 'resolveDuplicate', 'resolveHpcna', 'markDetailsChecked', 'submitFeedback',
  'recordPaperFeedback', 'addPaperResponse', 'releaseCertificate', 'releaseAllReady', 'correctCertificate', 'prepareMessage',
  'setMessageStatus', 'updateEvent', 'updateApproval', 'updateSignatory', 'addStaff', 'setStaffActive', 'setLogo', 'setPresenterPhoto'
]);
const MAX_CALLS = 120;
const MAX_BODY = 2_000_000;

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Max-Age': '86400'
};

export const SCHEMA_SQL = [
  `create table if not exists public.app_state (
     id text primary key,
     state jsonb not null,
     rev integer not null default 0,
     updated_at timestamptz not null default now())`,
  `create table if not exists public.app_state_history (
     id bigserial primary key,
     row_id text not null,
     rev integer not null,
     at timestamptz not null default now(),
     state jsonb not null)`,
  // Only this server program (connecting as the database owner) may read or write
  // these tables. The public website key gets no access at all.
  `alter table public.app_state enable row level security`,
  `alter table public.app_state_history enable row level security`,
  `revoke all on public.app_state from anon, authenticated`,
  `revoke all on public.app_state_history from anon, authenticated`
];

/**
 * deps:
 *  sql            postgres.js client (tagged template, sql.begin, sql.json)
 *  CPD            the rules engine (core.js)
 *  getUserEmail   async (accessToken, apikey) => email | null   (verifies a staff sign-in)
 *  dataset        'test' | 'live'
 *  initialStaff   [{ name, email, role }]  (administrators first)
 *  clock          () => ms   (optional, for tests)
 *  random         () => [0,1) (optional)
 */
export function createHandler(deps) {
  const { sql, CPD, getUserEmail } = deps;
  const dataset = deps.dataset === 'live' ? 'live' : 'test';
  // live and test data are kept in separate records ('main' is the test record)
  const ROW_ID = dataset === 'live' ? 'live' : 'main';
  const clock = deps.clock || (() => Date.now());
  const random = deps.random || cryptoRandom;
  let ready = null;

  function json(body, status) {
    return new Response(JSON.stringify(body), { status: status || 200, headers: Object.assign({ 'Content-Type': 'application/json' }, CORS) });
  }
  const ruleError = e => ({ ok: false, error: { code: e.code || 'error', message: e.message, errors: e.errors || null } });

  async function ensureReady() {
    if (!ready) ready = (async () => {
      for (const q of SCHEMA_SQL) await sql.unsafe(q);
      const rows = await sql`select 1 from public.app_state where id = ${ROW_ID}`;
      if (!rows.length) {
        const state = initialState();
        await sql`insert into public.app_state (id, state, rev) values (${ROW_ID}, ${sql.json(state)}, 0) on conflict (id) do nothing`;
      }
    })().catch(e => { ready = null; throw e; });
    return ready;
  }

  function initialState() {
    const now = clock();
    const ctx = { now, rand: random };
    const state = CPD.createState(dataset === 'live' ? 'live' : 'demo');
    state.createdAt = now;
    state.dataset = dataset;
    const list = (deps.initialStaff || []).slice().sort((a, b) => (a.role === 'admin' ? 0 : 1) - (b.role === 'admin' ? 0 : 1));
    for (const s of list) {
      const admin = state.staff.find(x => x.role === 'admin' && x.active);
      let actor = null;
      if (admin) { state.sessions.__seed = { staffId: admin.id }; actor = { session: '__seed' }; }
      CPD.addStaff(state, ctx, actor, { name: s.name, email: s.email, role: s.role });
    }
    state.sessions = {};
    return state;
  }

  function staffByEmail(state, email) {
    if (!email) return null;
    const e = email.toLowerCase();
    return state.staff.find(s => s.active && (s.email || '') === e) || null;
  }

  // ---- what each kind of visitor receives ----
  function publicBooking(b) {
    const out = JSON.parse(JSON.stringify(b));
    if (out.flags && out.flags.duplicate) out.flags.duplicate = { matches: [], resolved: out.flags.duplicate.resolved };
    out.exceptions = (out.exceptions || []).map(x => ({ id: x.id, type: x.type, resolved: x.resolved ? { at: x.resolved.at } : null }));
    if (out.completion) { delete out.completion.note; delete out.completion.reviewNote; }
    delete out.contingencyReason;
    return out;
  }
  function baseView(state, now) {
    return {
      schema: state.schema, mode: state.mode, dataset, rev: state.rev, event: state.event,
      staff: [], sessions: {}, bookings: [], responses: [], messages: [], certificates: [], audit: [],
      counters: state.counters, integration: state.integration, clock: { simulated: false, at: null, setAt: null }, scenario: null,
      summary: CPD.publicSummary(state, now), viewKind: 'public', now
    };
  }
  function viewFor(state, who, token, now) {
    if (who.staff) {
      const v = JSON.parse(JSON.stringify(state));
      v.sessions = { remote: { staffId: who.staff.id } };
      v.staff = v.staff.map(s => { const c = Object.assign({}, s); delete c.pinHash; delete c.failed; delete c.lockUntil; return c; });
      if (who.staff.role !== 'admin') { v.audit = []; v.responses = []; v.restricted = true; }
      v.dataset = dataset; v.summary = CPD.publicSummary(state, now); v.viewKind = 'staff'; v.now = now;
      return v;
    }
    const v = baseView(state, now);
    v.signedInNotStaff = !!who.email;
    if (token && token.value) {
      if (token.kind === 'cert') {
        const r = CPD.certByToken(state, token.value);
        if (r && r.booking) { v.bookings = [publicBooking(r.booking)]; v.certificates = [r.cert]; v.viewKind = 'attendee'; }
      } else {
        const b = CPD.bookingByToken(state, token.value);
        if (b) {
          v.bookings = [publicBooking(b)];
          v.certificates = state.certificates.filter(c => c.bookingId === b.id);
          v.waitlistPos = b.status === 'waitlisted' ? CPD.waitlist(state).findIndex(x => x.id === b.id) + 1 : null;
          v.viewKind = 'attendee';
        }
      }
    }
    return v;
  }

  // ---- running website requests through the rules engine ----
  const isActorArg = a => a && typeof a === 'object' && !Array.isArray(a) && Object.keys(a).length === 1 && 'session' in a;
  function prepareCalls(calls, who) {
    if (!Array.isArray(calls) || !calls.length) throw Object.assign(new Error('Nothing to do.'), { code: 'bad_request' });
    if (calls.length > MAX_CALLS) throw Object.assign(new Error('Too many changes in one request.'), { code: 'bad_request' });
    return calls.map(c => {
      const fn = c && c.fn, args = Array.isArray(c && c.args) ? c.args : null;
      const allowed = who.staff ? STAFF_FNS : PUBLIC_FNS;
      if (typeof fn !== 'string' || !args || !allowed.has(fn) || typeof CPD[fn] !== 'function')
        throw Object.assign(new Error(who.staff ? 'This action is not available.' : 'Please sign in as staff to do this.'), { code: who.staff ? 'perm' : 'auth' });
      // Whatever "actor" the browser sent is replaced by the signed-in staff member (or nobody).
      return { fn, args: args.map(a => (isActorArg(a) ? (who.staff ? { session: '__req' } : null) : a)) };
    });
  }
  function runCalls(state, calls, who, now) {
    const ctx = { now, rand: random };
    if (who.staff) state.sessions = { __req: { staffId: who.staff.id } }; else state.sessions = {};
    try {
      CPD.processExpiries(state, ctx);
      const results = [];
      for (const c of calls) {
        const r = CPD[c.fn](state, ctx, ...c.args);
        results.push(r === undefined ? null : JSON.parse(JSON.stringify(r)));
      }
      CPD.checkInvariants(state);
      return results;
    } finally { state.sessions = {}; }
  }

  async function withLockedState(fn) {
    return sql.begin(async tx => {
      const [row] = await tx`select state, rev from public.app_state where id = ${ROW_ID} for update`;
      const state = row.state;
      state.rev = row.rev;
      const out = await fn(state);
      if (out && out.save) {
        const rev = row.rev + 1;
        state.rev = rev;
        await tx`update public.app_state set state = ${sql.json(state)}, rev = ${rev}, updated_at = now() where id = ${ROW_ID}`;
        await tx`insert into public.app_state_history (row_id, rev, state)
                 select ${ROW_ID}, ${rev}, ${sql.json(state)}
                 where not exists (select 1 from public.app_state_history where row_id = ${ROW_ID} and at > now() - interval '1 hour')`;
      }
      return out;
    });
  }

  async function identify(req, body) {
    const h = req.headers.get('authorization') || '';
    const m = /^Bearer\s+(.+)$/i.exec(h);
    const bearer = m ? m[1].trim() : '';
    // the public website key is not a sign-in
    if (!bearer || bearer.startsWith('sb_publishable_') || bearer === (req.headers.get('apikey') || '')) return { email: null };
    let email;
    try { email = await getUserEmail(bearer, req.headers.get('apikey') || ''); }
    catch (e) { return { unavailable: true }; }
    if (!email) return { expired: true };
    return { email: email.toLowerCase() };
  }

  return async function handle(req) {
    if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
    if (req.method !== 'POST') return json({ ok: false, error: { code: 'bad_request', message: 'Use POST.' } }, 405);
    let body;
    try {
      const text = await req.text();
      if (text.length > MAX_BODY) return json({ ok: false, error: { code: 'too_large', message: 'The request is too large.' } }, 413);
      body = JSON.parse(text || '{}');
    } catch (e) { return json({ ok: false, error: { code: 'bad_request', message: 'Invalid request.' } }, 400); }
    try {
      await ensureReady();
      const id = await identify(req, body);
      if (id.unavailable) return json({ ok: false, error: { code: 'auth_unavailable', message: 'Staff sign-in could not be checked just now. Please try again in a moment.' } }, 503);
      if (id.expired) return json({ ok: false, error: { code: 'signed_out', message: 'Your sign-in has expired. Please sign in again.' } }, 401);
      const token = body.token && typeof body.token === 'object' && typeof body.token.value === 'string' && body.token.value.length <= 64
        ? { kind: body.token.kind === 'cert' ? 'cert' : 'booking', value: body.token.value } : null;
      const now = clock();

      if (body.op === 'view') {
        const [row] = await sql`select state, rev from public.app_state where id = ${ROW_ID}`;
        let state = row.state; state.rev = row.rev;
        // process any offers that have run out before showing the data
        if (state.bookings.some(b => b.status === 'offered' && b.offer && now >= b.offer.expiresAt)) {
          state = (await withLockedState(st => { const n = CPD.processExpiries(st, { now, rand: random }); return { save: n > 0, state: st }; })).state;
        }
        const who = { email: id.email, staff: staffByEmail(state, id.email) };
        return json({ ok: true, view: viewFor(state, who, token, now) });
      }

      if (body.op === 'act') {
        const out = await withLockedState(state => {
          const who = { email: id.email, staff: staffByEmail(state, id.email) };
          let calls;
          try { calls = prepareCalls(body.calls, who); } catch (e) { return { save: false, error: e }; }
          const before = JSON.stringify(state);
          try {
            let results = runCalls(state, calls, who, now);
            if (!who.staff) results = results.map(r => (r && r.token && r.ref ? publicBooking(r) : r));
            return { save: true, results, state, who };
          } catch (e) {
            if (e && e.name === 'RuleError') return { save: false, error: e, state: JSON.parse(before), who };
            throw e;
          }
        });
        if (out.error) return json(ruleError(out.error));
        // after a public booking, show the attendee their own booking
        let tk = token;
        if (!out.who.staff && !tk) { const b = out.results.find(r => r && r.token && r.ref); if (b) tk = { kind: 'booking', value: b.token }; }
        return json({ ok: true, results: out.results, view: viewFor(out.state, out.who, tk, now) });
      }
      return json({ ok: false, error: { code: 'bad_request', message: 'Unknown request.' } }, 400);
    } catch (e) {
      console.error(e);
      return json({ ok: false, error: { code: 'server', message: 'The server had a problem. Please try again in a moment.' } }, 500);
    }
  };
}

function cryptoRandom() {
  const a = new Uint32Array(1);
  globalThis.crypto.getRandomValues(a);
  return a[0] / 4294967296;
}
